        # Validate action
        if action not in (ModerationAction.APPEAL_APPROVED.value, ModerationAction.APPEAL_DENIED.value):
            return error_response(
                "VALIDATION_ERROR",
                "action must be 'APPEAL_APPROVED' or 'APPEAL_DENIED'",
