                status_code=429,
            )

        # Overlap detection (with buffer) - quota-aware
        has_conflict, overlap_count = _check_overlap(resource_id, start_time, end_time)
        slot_quota = _get_slot_quota(resource_id, start_time, end_time)
        if overlap_count >= slot_quota:
