                "SLOT_UNAVAILABLE",
                "The requested time slot overlaps with an existing reservation",
                status_code=409,
            )

        # Create reservation
        reservation = Reservation(
            user_id=current.user_id,
            resource_id=resource_id,
            organization_id=organization_id,
            status=ReservationStatus.HELD.value,
